__NUXT_JSONP__("/ru/stay", (function(a,b,c,d,e,f,g,h,i,j){return {data:[{details:{slug:"ru",pageTitle:"Проживание | Mentor Language Institute",pageDescription:"MLI сотрудничает с U.S. Support Services Inc.- это организация которая предоставляет жилье студентам ",title:"Проживание",subtitle:["MLI сотрудничает с U.S. Support Services Inc.- это организация которая предоставляет жилье студентам \u003Cbr \u002F\u003EДля получения более подробной информации посетите \u003Ca href=\"www.usssinc.net\u002Fru\" target=\"_blank\"\u003Ewww.usssinc.net.ru\u003C\u002Fa\u003E"],image:"\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-1.jpg",gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Faccommodation-3.jpg"],note:"Студенты могут выбрать проживание в семье или общежитии.",types:[{title:"Общежитие",description:["В общежитии 40 комнат. У вас будет возможность общаться с другими иностранными студентами.Мы рекомендуем вам остановиться в общежитии, если вы предпочитаете бюджетное место."],lists:["Комната: частная (индивидуальная), общая (2 человека) или четырехместная (4 человека)","Питание: Без питания [имеется полностью оборудованная кухня]","Конфиденциальность: в общежитиях больше приватности, чем в семье, однако существуют некоторые правила прибывания.","Поездка в школу: Поездка в школу: около 20 минут пешком или на автобусе."],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fdormitory-4.jpg"],prices:[{title:"Цены общежитя",table:{tableMaxCol:4,title:"Placement Fee* : $200\u003Cbr \u002F\u003EЕсли вам меньше 18 лет, арендная плата будет примерно на 10% выше, чем цена для студента старше 18 лет.",thead:[b,c,"Shared (2 people)","Quad (4 people)"],tbody:[[d,a,a,a],[e,"$550","$410",a],[f,"$1,100","$820","$600"],[g,"$1,650","$1,230","$900"],[h,"$2,200","$1,640","$1,200"],[i,"$4,160","$2,960","$2,160"],[j,"$6,240","$4,440","$3,240"]]},notes:["*Сбор за размещение взимается один раз. Невозвратный.\u003Cbr \u002F\u003E**Депозит за проживание будет возвращен после того как студет освободит комнату."]}]},{title:"Проживание в семье",description:["Студенты, которые предпочитают жить с семьей, ищут безопасную, гостеприимную, и комфортную атмосферу, в которой они могут практиковать свои навыки английского языка. Это также возможность узнать об американских обычаях, традициях и семейных ценностях."],lists:["Комната: Частная (Индивидуальная)","Питание: 2-х разовое питание (завтрак и ужин)","Конфиденциальность. В зависимости от принимающей семьи существуют некоторые домашние правила.","Поездка в школу: 30-45 минут в среднем на автобусе"],gallery:["\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-1.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-2.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-3.jpg","\u002Fimages\u002Flocation\u002Faccommodations\u002Fhomestay-4.jpg"],prices:[{title:"Цены на проживание в семье",table:{tableMaxCol:3,title:"Placement Fee* : $300\u003Cbr \u002F\u003EЕсли вам меньше 18 лет, арендная плата будет примерно на 10% выше, чем цена для студента старше 18 лет.",thead:[b,c,"Shared***"],tbody:[[d,a,a],[e,"$436","$384"],[f,"$872","$768"],[g,"$1,308","$1,152"],[h,"$1,744","$1,536"],[i,"$3,160","$2,904"],[j,"$4,740","$4,356"]]},notes:["*Сбор за размещение взимается один раз. Невозвратный.\u003Cbr \u002F\u003E**Депозит за проживание будет возвращен после того как студет освободит комнату.\u003Cbr \u002F\u003E***Если вы хотите проживать в комнате на двоих  \u003Cspan class=\"rmarker\"\u003Eвы должы самостоятельно выбрать себе соседа.\u003C\u002Fspan\u003E"]}]}],comments:{title:"Комментарии наших сотрудников",description:["Будет нелегко найти место для проживания, когда вы впервые приедете в США,особенно для иностранных студентов, не имеющих номера социального страхования (SSN) и кредитной истории. В большинстве мест для аренды требуется как SSN, так и кредитная история. Поэтому мы рекомендуем вам остановится в наших предлогаемых вариантах, по крайней мере, на первые пару месяцев.","※ Ваше размещение будет предоставлено Службой поддержки США или другими агентами."]},dir:"\u002Fstay",path:"\u002Fstay\u002Fru",extension:".json",createdAt:"2026-10-22T16:31:31.107Z",updatedAt:"2025-05-26T12:06:27.920Z"}}],fetch:{},mutations:void 0}}("$300","","Private (Individual)","\u003Cb\u003EDeposit\u003C\u002Fb\u003E","1 week","2 weeks","3 weeks","4 weeks","8 weeks","12 weeks")));